using Microsoft.EntityFrameworkCore;using OperationsRequests.Data;using OperationsRequests.Domain;using OperationsRequests.Services;namespace OperationsRequests.Tests;public class WorkflowTests{static (ApplicationDbContext,TrainingRequest,ApplicationUser) Setup(RequestPriority p=RequestPriority.Medium){var db=new ApplicationDbContext(new DbContextOptionsBuilder<ApplicationDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).Options);var r=new TrainingRequest{Id=1,Priority=p,Status=RequestStatus.UnderReview,RequestedById="staff",Site=new Site{Id=7,TerritoryId=3,Territory=new Territory{Id=3,CountryId=2}}};db.TrainingRequests.Add(r);db.SaveChanges();return(db,r,new ApplicationUser{Id="manager",DisplayName="Manager",TerritoryId=3,CountryId=2,IsActive=true});}static RequestWorkflowService Service(ApplicationDbContext db)=>new(db);[Fact]public async Task Decline_requires_reason(){var(db,r,u)=Setup();var x=await Service(db).Act(r,u,[Roles.TerritoryManager],"Decline",null,[]);Assert.False(x.Item1);Assert.Equal(RequestStatus.UnderReview,r.Status);}[Fact]public async Task High_priority_requires_country_manager(){var(db,r,u)=Setup(RequestPriority.High);var x=await Service(db).Act(r,u,[Roles.TerritoryManager],"Approve","ok",[]);Assert.False(x.Item1);}[Fact]public async Task Approve_creates_audit(){var(db,r,u)=Setup();var x=await Service(db).Act(r,u,[Roles.TerritoryManager],"Approve","ok",[]);Assert.True(x.Item1);Assert.Equal(RequestStatus.Approved,r.Status);Assert.Single(db.AuditEvents);}[Fact]public async Task Self_approval_is_blocked(){var(db,r,u)=Setup();u.Id="staff";var x=await Service(db).Act(r,u,[Roles.TerritoryManager],"Approve","ok",[]);Assert.False(x.Item1);}[Fact]public async Task Resolution_requires_note(){var(db,r,u)=Setup();r.Status=RequestStatus.Approved;var x=await Service(db).Act(r,u,[Roles.TerritoryManager],"Resolve",null,[]);Assert.False(x.Item1);}}
